[CmdletBinding()]param([Parameter(Mandatory)][string]$AppId,[Parameter(Mandatory)][string]$Version,[Parameter(Mandatory)][string]$Destination)
Import-Module (Join-Path $PSScriptRoot 'Discovery.Release.psm1') -Force
$tag="$AppId/v$Version";$assetName="$AppId-$Version.zip";$release=Get-GithubReleaseByTag $tag;if(-not $release){throw "No release found for tag '$tag'."};$asset=@($release.assets|Where-Object name -ceq $assetName|Select-Object -First 1);if(-not $asset.Count){throw "Release '$tag' has no asset named '$assetName'."};[void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetFullPath($Destination));$archive=Join-Path $Destination $assetName;Save-GithubReleaseAsset $asset[0] $archive;Expand-ArtifactZip $archive $Destination;Remove-Item -LiteralPath $archive -Force;Write-Host "Fetched $assetName from '$tag' into $Destination."
